import { HttpClient } from '@angular/common/http';
import { Component, ElementRef, OnInit, ViewChild } from '@angular/core';
import { ToastService } from '../../../common/toast.service';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { environment } from '../../../../environments/environment';
declare var bootstrap: any;

@Component({
  selector: 'app-state-gallery',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './state-gallery.component.html',
  styleUrl: './state-gallery.component.scss'
})
export class StateGalleryComponent implements OnInit {
  @ViewChild('galleryOffcanvas') galleryOffcanvas!: ElementRef;
  selectedImages: string[] = [];
  apiUrl = `${environment.apiUrl}/gallery`;
  bulkUrl = `${environment.apiUrl}/gallery/bulk`;
  galleryImages: any[] = []; // for fetched gallery images
  deleteMode = false; // toggle delete mode

  constructor(private http: HttpClient, private toast: ToastService) { }
  ngOnInit(): void {
    this.loadGallery();
  }
  openOffcanvas() {
    const offcanvas = new bootstrap.Offcanvas(this.galleryOffcanvas.nativeElement);
    offcanvas.show();
  }

onFileSelected(event: any) {
  const files: FileList = event.target.files;

  for (let i = 0; i < files.length; i++) {
    const file = files[i];

    // Optional: skip large files
    if (file.size > 5 * 1024 * 1024) {
      alert(`${file.name} exceeds 5MB and will not be uploaded.`);
      continue;
    }

    const reader = new FileReader();
    reader.onload = (e: any) => {
      this.selectedImages.push(e.target.result); // preview image
    };
    reader.readAsDataURL(file);
  }
}
  loadGallery() {

    this.http.get<any>(this.apiUrl,).subscribe({
      next: (res) => {
        if (res.success && res.data) {
          this.galleryImages = res.data;
        }
      },
      error: (err) => {
        console.error('Error loading gallery:', err);
      }
    });
  }
  removeImage(index: number) {
    this.selectedImages.splice(index, 1);
  }

  onSubmit() {
    if (this.selectedImages.length === 0) {
      this.toast.showToast('Please upload at least one image', 'error');
      return;
    }
    const payload = {
      images: this.selectedImages.map(img => ({ image: img }))
    };

    this.http.post(this.bulkUrl, payload).subscribe({
      next: (res: any) => {
        this.toast.showToast('Images uploaded successfully!', 'success');
        this.selectedImages = [];
        this.loadGallery();
        const offcanvas = bootstrap.Offcanvas.getInstance(this.galleryOffcanvas.nativeElement);
        offcanvas?.hide();
      },
      error: (err) => {
        console.error(err);
        this.toast.showToast('Upload failed', 'error');
      }
    });
  }

    deleteImage(id: number) {

    this.http.delete(`${this.apiUrl}/${id}`).subscribe({
      next: () => {
        this.toast.showToast('Image deleted successfully!', 'success');
        this.loadGallery();
      },
      error: () => this.toast.showToast('Failed to delete image', 'danger')
    });
  }

  /** Toggle delete mode */
  toggleDeleteMode() {
    this.deleteMode = !this.deleteMode;
  }
}

